import 'package:flutter/material.dart';import 'package:myapp/models/user_model.dart';import 'package:myapp/repositories/user_repository.dart';import 'package:myapp/utils/colors.dart';class GoalsViewModel extends ChangeNotifier {  final UserRepository _userRepository;  UserModel? _currentUser;  Map<String, Map<String, dynamic>> _goals = {};  GoalsViewModel(this._userRepository);  UserModel? get currentUser => _currentUser;  void setUser(UserModel? user) {    _currentUser = user;    loadGoals();  }  Map<String, Map<String, dynamic>> get goals => _goals;  void loadGoals() {    if (_currentUser != null) {      _goals = Map<String, Map<String, dynamic>>.from(        (_currentUser!.goals)            .map((k, v) => MapEntry(k, Map<String, dynamic>.from(v))),      );    }    notifyListeners();  }  Future<void> saveGoals() async {    if (_currentUser != null) {      _currentUser!.goals = Map.from(_goals);      await _userRepository.updateUser(_currentUser!);    }  }  Future<void> updateGoal(String key, Map<String, dynamic> newGoal) async {    _goals[key] = Map.from(newGoal);    await saveGoals();    notifyListeners();  }  Future<void> toggleGoalActive(String key, bool active) async {    if (_goals.containsKey(key)) {      _goals[key]!['active'] = active;      await saveGoals();      notifyListeners();    }  }  int get activeCount => _goals.values.where((g) => g['active'] == true).length;  int get completedCount {    int count = 0;    _goals.forEach((key, goal) {      if (goal['active'] == true &&          key == 'weight' &&          goal['current'] != null) {        if (getProgress(key) >= 1.0) count++;      }    });    return count;  }  double getProgress(String key) {    final goal = _goals[key];    if (goal == null || goal['current'] == null) return 0.0;    if (key == 'weight') {      final double target = _toDouble(goal['target']) ?? 0.0;      final double current = _toDouble(goal['current']) ?? 0.0;      final String goalType = goal['goalType'] ?? 'lose';      if (goalType == 'lose') {        final double startWeight = _toDouble(goal['startWeight']) ??            (current > target ? current : target + 5.0);        final double totalToLose = startWeight - target;        if (totalToLose <= 0) return 1.0;        return ((startWeight - current) / totalToLose).clamp(0.0, 1.0);      } else if (goalType == 'gain') {        final double startWeight = _toDouble(goal['startWeight']) ??            (current < target ? current : target - 5.0);        final double totalToGain = target - startWeight;        if (totalToGain <= 0) return 1.0;        return ((current - startWeight) / totalToGain).clamp(0.0, 1.0);      } else if (goalType == 'maintain') {        if (target == 0) return 0.0;        final double diff = (current - target).abs();        if (diff <= (target * 0.01)) return 1.0;        return (1.0 - (diff / 5.0)).clamp(0.0, 1.0);      }    }    final double targetValue = _toDouble(goal['target']) ?? 0.0;    final double currentValue = _toDouble(goal['current']) ?? 0.0;    if (targetValue == 0) return 0.0;    return (currentValue / targetValue).clamp(0.0, 1.0);  }  int getProgressPercentage(String key) {    return (getProgress(key) * 100).toInt();  }  Color getProgressColor(String key) {    final progress = getProgress(key);    return progress >= 1.0        ? greenColor        : progress >= 0.75            ? blueColor            : progress >= 0.5                ? orangeColor                : redColor;  }  bool shouldShowPercentage(String key) {    final goal = _goals[key];    if (goal == null) return false;    return key == 'weight' && goal['current'] != null;  }  bool shouldShowProgressBar(String key) {    final goal = _goals[key];    if (goal == null) return false;    return key == 'weight' && goal['current'] != null;  }  String getGoalStatus(String key) {    final goal = _goals[key]!;    if (key == 'calories' || key == 'protein') return 'Goal Set';    if (key == 'weight' && goal['current'] != null) {      return getProgress(key) >= 1.0 ? 'Goal achieved' : 'Active';    }    return 'Not started';  }  Color getCardColor(String key) {    switch (key) {      case 'calories':        return redColor;      case 'protein':        return orangeColor;      case 'weight':        return blueColor;      default:        return primaryColor;    }  }  String getShortTitle(String key) {    switch (key) {      case 'calories':        return 'Calories';      case 'protein':        return 'Protein';      case 'weight':        return 'Weight';      default:        return _capitalize(key);    }  }  IconData getIcon(String key) {    switch (key) {      case 'calories':        return Icons.local_fire_department;      case 'protein':        return Icons.restaurant;      case 'weight':        return Icons.monitor_weight;      default:        return Icons.flag;    }  }  String _capitalize(String s) =>      s.isNotEmpty ? s[0].toUpperCase() + s.substring(1) : '';  double? _toDouble(dynamic value) {    if (value == null) return null;    if (value is int) return value.toDouble();    if (value is double) return value;    return double.tryParse(value.toString());  }  static String getGoalDescription(String key) {    switch (key) {      case 'weight':        return 'Target body weight';      case 'calories':        return 'Daily calorie intake';      case 'protein':        return 'Daily protein intake';      default:        return 'Fitness goal';    }  }  static IconData getGoalIcon(String key) {    switch (key) {      case 'weight':        return Icons.monitor_weight;      case 'calories':        return Icons.local_fire_department;      case 'protein':        return Icons.restaurant;      default:        return Icons.flag;    }  }}